  public var source: UInt64
  /// Map snapshot generation that the event reports, or zero when source_type
  /// is `MLN_RUNTIME_EVENT_SOURCE_RUNTIME`.
  public var generation: UInt64
  /// Secondary event detail whose meaning type selects; see
  /// `mln_runtime_event_type`.
  public var code: Int32
  /// Borrowed UTF-8 message bytes, empty when this event carries no message.
  public var message: String
  /// Typed payload selected by payload_type.
  public var payload: RuntimeEventPayload
  public static var `default`: Self {
    Self()
  }

  public init(
    type: RuntimeEventType = .init(rawValue: 0),
    sourceType: RuntimeEventSourceType = .init(rawValue: 0),
    source: UInt64 = 0,
    generation: UInt64 = 0,
    code: Int32 = 0,
    message: String = "",
    payload: RuntimeEventPayload = .default
  ) {
    self.type = type
    self.sourceType = sourceType
    self.source = source
    self.generation = generation
    self.code = code
    self.message = message
    self.payload = payload
  }

  init(
    raw: mln_runtime_event,
    recordBytes: UnsafeRawBufferPointer? = nil
  ) throws {
    type = RuntimeEventType(rawValue: raw.type)
    sourceType = RuntimeEventSourceType(rawValue: raw.source_type)
    source = raw.source
    generation = raw.generation
    code = raw.code
    message = try NativeString.copyUTF8(
      data: raw.message.data,
      size: raw.message.size
    )
    payload = try { () throws -> RuntimeEventPayload in
      switch raw
        .payload_type
      {
      case MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME
        .rawValue: return .renderFrame(RuntimeEventRenderFrame(raw: raw.payload
            .render_frame)) case MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP
                  .rawValue: return .renderMap(RuntimeEventRenderMap(raw: raw
            .payload
            .render_map)) case MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION
                  .rawValue: return .tileAction(RuntimeEventTileAction(raw: raw
            .payload
            .tile_action)) case MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS
                  .rawValue: return .offlineRegionStatus(
          RuntimeEventOfflineRegionStatus(raw: raw
            .payload
            .offline_region_status)
        ) case MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR
        .rawValue: return .offlineRegionResponseError(
          RuntimeEventOfflineRegionResponseError(raw: raw
            .payload
            .offline_region_response_error)
        ) case MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT
        .rawValue: return .offlineRegionTileCountLimit(
          RuntimeEventOfflineRegionTileCountLimit(raw: raw
            .payload
            .offline_region_tile_count_limit)
        ) case MLN_RUNTIME_EVENT_PAYLOAD_NONE
        .rawValue: return .none default: return .unknown(
          raw.payload_type,
          recordBytes
            .map {
              Data($0
                .dropFirst(MemoryLayout<mln_runtime_event>
                  .offset(of: \.payload)!))
            } ??
            withUnsafeBytes(of: raw.payload) { Data($0) }
        )
      }
    }()
  }
}

